    rpanels = regions(h, row_seps)
    cpanels = regions(w, col_seps)

    for ri in range(len(rpanels) - 1):
        r0, r1 = rpanels[ri]
        r2, r3 = rpanels[ri + 1]
        ph0, ph1 = r1 - r0 + 1, r3 - r2 + 1
        if ph0 != ph1:
